/* Role-specific study guides: Content, Creator Partnerships, Affiliate, Community.
 * Requires global G() and ROLE_STUDY_GUIDES from role-study-guides-part1.js.
 * Synthetic figures are explicitly labelled and are not client results.
 */
var ROLE_STUDY_GUIDES_PART3 = {
content:[
G("Content Strategy dimulai dari business objective, audience need, brand positioning, and communication role. Content bukan sekadar kalender posting; ia adalah sistem aset yang membantu audience memahami, mempertimbangkan, memilih, menggunakan, dan merekomendasikan brand. Brand voice harus memiliki prinsip, tone, vocabulary, and boundaries yang konsisten, tetapi dapat diekspresikan secara native pada tiap platform.",
"SIMULATED — brand ingin dikenal sebagai ahli finansial yang mudah dipahami. Tone harus sederhana dan membumi, tetapi tetap akurat; TikTok dapat memakai storytelling, LinkedIn memakai insight profesional, dan blog menjelaskan detail tanpa mengubah brand promise.",
["<b>Define audience and role.</b> Tentukan audience need, stage, channel context, and business task content.","<b>Write voice principles.</b> Tetapkan personality, tone dimensions, vocabulary, evidence bar, and prohibited claims.","<b>Build examples.</b> Tunjukkan same proposition dalam format platform yang berbeda.","<b>Set governance.</b> Tetapkan approver, accessibility, legal review, update, and response rules."],
"Buat brand voice guide dengan 4 prinsip, tone matrix, vocabulary, do/don't, claims policy, dan contoh adaptasi satu message untuk TikTok, Instagram, YouTube, LinkedIn, dan blog.",[["Apa beda brand voice dan tone?","Brand voice adalah karakter komunikasi yang relatif konsisten; tone menyesuaikan ekspresi voice terhadap konteks, platform, dan audience."],["Mengapa brand voice tidak boleh menghalangi platform-native content?","Ekspresi perlu menyesuaikan format dan perilaku audience sambil mempertahankan promise dan principles."],["Apa yang termasuk claims policy?","Claims policy menetapkan batas klaim, proof requirement, legal atau regulatory review, dan pernyataan yang tidak boleh digunakan."]],[["Brand voice","Karakter bahasa/kepribadian brand yang konsisten."],["Tone","Tone adalah nuansa ekspresi brand voice yang disesuaikan dengan konteks, audience, channel, dan tujuan komunikasi."],["Content role","Tugas aset konten dalam journey."],["Claims policy","Aturan bukti dan approval untuk pernyataan brand."]],"DPA-T13-CH01"),
G("Content strategy menerjemahkan objective campaign/business menjadi content objectives, territories, pillars, formats, and distribution roles. Content pillar bukan sekadar daftar tema; tiap pillar harus memiliki audience need, brand role, proof, format, and measurement. Pisahkan content untuk education, consideration, conversion, retention, and advocacy. Proporsi konten perlu mengikuti objective, resources, and evidence—not fixed universal percentages.",
"SIMULATED — brand skincare memiliki pillars ingredient education, routine, proof, and community stories. Jika semua content hanya promotional offer, brand gagal menjawab research needs; jika semua education tanpa product proof, journey ke consideration juga lemah.",
["<b>Map objective to content task.</b> Tentukan awareness, education, proof, conversion, onboarding, and retention roles.","<b>Build pillars.</b> Tetapkan audience question, brand POV, evidence, formats, CTA, and owner.","<b>Set format mix.</b> Pilih long/short, video/article/carousel/newsletter, and accessibility needs.","<b>Define measurement.</b> Pilih KPI sesuai task; hindari view/follower sebagai universal metric."],
"Buat content strategy one-pager dengan objectives, audience journey, 4–6 content pillars, formats, distribution, channel role, KPIs, owner, and resource assumptions.",
[["Apa beda content pillar dan editorial calendar?","Pillar menentukan territory/strategic themes; calendar mengatur kapan dan aset mana yang diproduksi/publish."],["Mengapa persentase content mix tidak universal?","Kategori, audience, funnel, budget, and business objective berbeda; proporsi harus ditentukan dari evidence."],["Kapan content dianggap mendukung conversion?","Saat ia menjawab objection, membuktikan value, memfasilitasi decision, and mengarah ke next action yang relevan."]],
[["Content pillar","Tema strategis yang menyusun sistem konten."],["Content objective","Perubahan yang dituju oleh suatu aset/kumpulan konten."],["Format mix","Kombinasi artikel, video, short-form, carousel, email, and other formats."],["Editorial territory","Ruang topik/narasi yang konsisten dengan audience dan brand."]],"DPA-T13-CH02"),
G("Editorial architecture mengatur alur ide, brief, production, review, publish, repurpose, and update. Calendar harus memuat objective, audience, pillar, format, channel, owner, asset status, approval, dependencies, dates, and KPI. Always-on dan campaign content memiliki ritme berbeda. Capacity planning penting agar kalender realistis dan tidak mendorong kuantitas dengan mengorbankan editorial quality.",
"SIMULATED — tim memiliki kapasitas dua video dan satu artikel per minggu. Calendar 10 asset per minggu membuat overdue dan review terburu-buru. Editorial system harus menyeimbangkan campaign deadlines, evergreen needs, and production bandwidth.",
["<b>Design workflow.</b> Map ideation, brief, research, draft, production, review, approval, publishing, and update.","<b>Build calendar schema.</b> Isi owner, channel, format, objective, pillar, due dates, assets, approvals, and KPI.","<b>Plan capacity.</b> Perkirakan hours, dependencies, production resources, and contingency.","<b>Govern status.</b> Gunakan status, version, feedback, accessibility, and archive."],
"Buat editorial calendar 4 minggu dengan 12 planned assets, status workflow, owner, deadlines, production effort, campaign dependencies, repurpose plan, and KPI.",[["Mengapa calendar harus memuat status/owner?","Tanpa status dan owner, tim tidak dapat mengelola approval, dependencies, delays, and accountability."],["Apa beda always-on dan campaign content?","Always-on content memenuhi kebutuhan audience yang berulang; campaign content terikat objective, timing, dan aktivasi tertentu."],["Bagaimana mengatasi kapasitas produksi terbatas?","Prioritaskan audience dan business value, repurpose materi, gunakan modular assets, lalu tetapkan cadence yang realistis."]],
[["Editorial architecture","Sistem struktur topic, formats, workflow, ownership, and distribution."],["Always-on content","Aset rutin yang melayani kebutuhan berulang."],["Production capacity","Jumlah output yang dapat diproduksi dengan resource/waktu tersedia."],["Content lifecycle","Alur dari ide hingga update/archive."]],"DPA-T13-CH03"),
G("Insight mining menggabungkan search, social listening, comments, competitor content, community, consumer research, and campaign performance untuk menemukan content gaps dan audience tensions. Ide konten perlu berasal dari audience questions, not solely trend chasing. Opportunity sizing menilai reach, relevance, urgency, competition, brand permission, production effort, and ability to differentiate.",
"SIMULATED — banyak komentar bertanya 'berapa lama hasil terlihat?' tetapi content brand hanya berisi product features. Insight menunjukkan need for realistic expectations and proof; konten educational dapat menjawab pertanyaan sekaligus mengurangi customer-service load.",
["<b>Collect signals.</b> Ambil search queries, comments, questions, support tickets, creator formats, and competitor gaps.","<b>Cluster needs.</b> Kelompokkan problem, misconception, objection, usage task, and cultural context.","<b>Validate insight.</b> Cari evidence across sources, volume, recency, and representative limits.","<b>Size opportunity.</b> Score relevance, audience value, differentiation, effort, and business role."],
"Buat insight-mining board 20 signals, cluster audience questions, validate three tensions, lalu prioritaskan lima content opportunities dengan score dan evidence trail.",[["Mengapa tren viral belum tentu opportunity?","Tren bisa tidak relevan dengan audience, category, atau brand dan belum tentu mendukung objective maupun outcome yang diinginkan."],["Apa tanda insight mining berkualitas?","Signals dapat ditelusuri, cluster menjelaskan need/tension, evidence lintas sumber, and content action jelas."],["Apa beda audience question dan brand talking point?","Audience question berasal dari kebutuhan mereka; brand talking point berasal dari hal yang ingin disampaikan brand."]],
[["Insight mining","Proses menemukan kebutuhan/tension dari beragam data/sinyal."],["Content gap","Pertanyaan/intent yang belum dilayani dengan baik."],["Opportunity sizing","Penilaian nilai, reach, relevance, effort, and feasibility."],["Audience tension","Kebutuhan yang berkonflik atau hambatan utama audience."]],"DPA-T13-CH04"),
G("Storytelling architecture membangun narasi dari hook, audience tension, problem, context, transformation, proof, and payoff. Hook menarik perhatian tetapi tidak boleh misleading. Brand POV memberi sudut pandang; story harus tetap factual, useful, and memorable. Format short-form perlu segera menyampaikan context/value, sedangkan long-form dapat membangun argument lebih lengkap. Narrative harus terhubung ke proposition dan CTA.",
"SIMULATED — hook 'cara hemat 50% biaya' digunakan, tetapi isi hanya memberi diskon 5%. Click/view mungkin naik, tetapi trust turun. Hook yang baik menjanjikan sesuatu yang benar-benar dibuktikan oleh konten.",
["<b>Choose audience tension.</b> Tulis konflik/need yang ingin diangkat dan mengapa relevan.","<b>Build narrative arc.</b> Rancang hook, context, stakes, insight, proof, transformation, and payoff.","<b>Express brand POV.</b> Pastikan sudut pandang punya evidence and relevance, bukan forced sales pitch.","<b>Adapt to format.</b> Atur opening, pacing, captions, visuals, audio, and CTA sesuai platform."],
"Buat tiga storyboards untuk satu insight: 15-second video, 60-second video, and long-form article. Sertakan hook, tension, beat sheet, proof, visual/audio notes, and CTA.",[["Apa risiko hook clickbait?","Hook yang menjanjikan hal berlebihan dapat mengecewakan audience, meningkatkan bounce atau negative feedback, dan menurunkan brand trust."],["Apa beda tension dan problem statement?","Tension menangkap konflik/need audience secara naratif; problem statement memformulasikan hambatan untuk keputusan."],["Apa fungsi proof dalam storytelling?","Proof memberi dasar untuk mempercayai claim dan membedakan cerita yang dapat dipertanggungjawabkan dari opini atau hiburan tanpa bukti."]],
[["Hook","Pembuka yang menarik perhatian dan menetapkan relevansi."],["Narrative arc","Struktur perkembangan cerita dari awal sampai payoff."],["Brand POV","Sudut pandang khas brand yang didukung evidence."],["Beat sheet","Urutan bagian/adegan penting dalam story."]],"DPA-T13-CH05"),
G("Long-form content membutuhkan riset, struktur, evidence, editorial clarity, and search/user intent. Artikel, newsletter, founder POV, case study, blog, whitepaper, and thought leadership memiliki depth dan reader task berbeda. Outline perlu argument, source, examples, proof, author expertise, internal/external links, and CTA. Content accuracy dan legal claim review penting terutama pada finance/health/regulated categories.",
"SIMULATED — artikel 'panduan memilih kartu kredit' mencantumkan benefit tetapi tidak menyebut fees, eligibility, risks, or comparison method. Konten menjadi tidak seimbang dan berpotensi menyesatkan; editorial review perlu fact-check and disclosure.",
["<b>Define reader task.</b> Tentukan search/consumer intent, knowledge level, and action.","<b>Research sources.</b> Gunakan primary/official sources, expert interviews, data, and citations; record access date.","<b>Build structure.</b> Susun thesis, outline, evidence, examples, visuals, summary, and CTA.","<b>Edit and publish.</b> Review accuracy, claims, readability, accessibility, SEO basics, and update ownership."],
"Buat brief dan outline long-form 1.200–1.500 kata dengan thesis, audience, sources, evidence table, section hierarchy, visual suggestions, author review, and CTA.",[["Mengapa long-form membutuhkan source trail?","Source trail membantu pembaca dan editor memeriksa klaim, angka, freshness, konteks, dan kredibilitas sebelum konten dipublikasikan."],["Apa risiko memakai sumber sekunder tanpa cross-check?","Angka/claim bisa outdated, salah konteks, atau hanya mengutip sumber lain yang sama."],["Kapan artikel harus diperbarui?","Perbarui ketika data, policy, product, platform, legal claim, atau search intent berubah sehingga isi lama berisiko menyesatkan."]],
[["Editorial brief","Dokumen scope, reader, angle, evidence, outline, and CTA."],["Primary source","Sumber langsung/original seperti official data, report, laws, or research."],["Thought leadership","Konten yang menyampaikan insight/POV berbasis expertise."],["Fact-check","Verifikasi klaim dengan sumber dan evidence."]],"DPA-T13-CH06"),
G("Short-form content mengoptimalkan ide menjadi video/carousel/short posts dengan pacing, retention, visual hierarchy, sound, captions, and platform-specific constraints. Repurposing bukan copy-paste; satu source idea dapat dipecah menjadi multiple angles, hooks, formats, and audience stages. Batch production membantu efisiensi tetapi membutuhkan asset naming, versioning, and quality control.",
"SIMULATED — satu webinar 30 menit diubah menjadi 10 clips. Tanpa editorial selection, semua clip dimulai lambat dan tidak memberi context. Repurposing yang baik memilih moments, rewrite hooks, add captions, and check standalone completeness.",
["<b>Select content moments.</b> Identifikasi insight, demonstration, objection, story, and proof from source asset.","<b>Design short-form.</b> Tentukan first-frame, hook, beat, captions, visual, audio, CTA, and duration.","<b>Repurpose intelligently.</b> Sesuaikan narrative/format per channel, bukan memotong secara mekanis.","<b>QA and package.</b> Periksa subtitles, safe zones, aspect ratio, audio rights, cover, filename, and versions."],
"Buat repurpose matrix 1 long-form source menjadi 8 assets: 3 short videos, 2 carousels, 1 email, 1 LinkedIn post, and 1 story. Sertakan hook, audience, format, CTA, and production notes.",[["Apa beda repurposing dan reposting?","Repurposing mengadaptasi angle, structure, format, and CTA untuk audience/context; reposting mengulang asset."],["Mengapa first-frame penting?","First-frame memberi konteks dan relevansi dengan cepat, membantu audience memahami nilai konten, serta memengaruhi keputusan untuk melanjutkan."],["Apa yang harus dicek pada video short-form?","Aspect ratio, safe zones, captions, audio rights, claims, brand visibility, and link/CTA behavior."]],
[["Repurposing","Mengadaptasi ide/asset ke format dan audience lain."],["Retention curve","Pola audience tetap menonton sepanjang durasi."],["Safe zone","Area visual yang tidak tertutup UI."],["Batch production","Memproduksi sejumlah asset dalam satu workflow/sesi."]],"DPA-T13-CH07"),
G("Platform adaptation mempertimbangkan audience behavior, native formats, discovery mechanics, content length, interaction, and professional/community context. TikTok, Instagram Reels, YouTube Shorts tidak identik; LinkedIn memiliki expectation profesional dan context berbeda. Adaptasi tetap menjaga proposition/brand voice tetapi mengubah hook, depth, visual, pace, CTA, and publishing metadata sesuai platform.",
"SIMULATED — materi yang sama dibagikan verbatim di TikTok, LinkedIn, and YouTube. TikTok membutuhkan hook dan demo cepat; LinkedIn memerlukan point of view/insight; YouTube dapat mendukung explainer lebih dalam. Satu caption tidak cocok untuk semuanya.",
["<b>Map platform role.</b> Tentukan discovery, depth, community, professional credibility, or entertainment role.","<b>Translate the idea.</b> Adapt hook, format, proof, length, language, CTA, and comment interaction.","<b>Check platform specs/policy.</b> Validate dimensions, captions, music, disclosure, and account features.","<b>Measure by context.</b> Compare metrics that match platform task, not raw views alone."],
"Buat one-idea/multi-platform adaptation matrix untuk TikTok, Instagram, YouTube, and LinkedIn. Sertakan hook, format, depth, CTA, native behavior, KPI, and risk per platform.",[["Mengapa satu content format tidak selalu cocok lintas platform?","Audience intent, consumption context, platform distribution, interaction behavior, and format constraints berbeda."],["Apa yang harus konsisten?","Brand promise, factual accuracy, point of view, dan key message harus konsisten; format, length, dan execution dapat diadaptasi."],["Mengapa metrics lintas platform tidak boleh dibandingkan mentah?","Definitions, view thresholds, audience, and platform behavior berbeda; gunakan normalized task-specific metrics."]],
[["Platform-native","Format/ekspresi yang sesuai mekanisme dan ekspektasi platform."],["Adaptation matrix","Perbandingan perubahan format/pesan per channel."],["CTA","Call to action yang meminta langkah berikutnya."],["Engagement context","Cara audience berinteraksi sesuai platform."]],"DPA-T13-CH08"),
G("Distribution and amplification menentukan bagaimana konten menjangkau audience melalui organic, paid, creator/KOL, community, newsletter, website, and partner channels. Distribution strategy bukan tugas setelah produksi; format, rights, timing, and measurement harus direncanakan di awal. Paid amplification sebaiknya memperkuat asset yang punya audience/creative fit, bukan menjadi jalan pintas untuk konten yang tidak menyelesaikan need.",
"SIMULATED — satu educational video perform baik organic tetapi usage rights creator tidak mengizinkan paid amplification. Campaign perlu memperoleh license/permission sebelum whitelisting atau repurposing.",
["<b>Set distribution role.</b> Tentukan channel, audience, objective, timing, owner, and cost.","<b>Confirm rights.</b> Periksa music, creator usage, UGC permission, whitelisting, exclusivity, and duration.","<b>Plan amplification.</b> Tentukan paid audience, budget, asset versions, landing/CTA, and test design.","<b>Measure cross-channel.</b> Track organic/paid separately, assisted visits, content quality, and downstream outcomes."],
"Buat distribution plan untuk 5 content assets: organic, paid, creator, community, newsletter, and website. Sertakan rights, owner, schedule, amplification trigger, KPI, and cross-channel caveats.",[["Mengapa paid boost bukan pengganti distribution strategy?","Amplification perlu audience fit, asset quality, rights, objective, budget, and downstream measurement."],["Apa risiko UGC/creator asset digunakan berbayar tanpa rights?","Penggunaan tanpa rights dapat melanggar IP atau usage agreement, merusak hubungan creator, dan menimbulkan policy maupun legal exposure."],["Bagaimana memisahkan hasil organic dan paid?","Gunakan tagging, platform reporting, asset IDs, time windows, and clearly defined attribution."]],
[["Amplification","Meningkatkan distribusi asset melalui paid/partner resources."],["Usage rights","Izin penggunaan asset/identitas creator pada channel/periode tertentu."],["Whitelisting","Penggunaan akun/identity creator untuk menjalankan paid ads sesuai permission."],["Distribution plan","Rencana kanal, audience, timing, owner, rights, and measurement."]],"DPA-T13-CH09"),
G("Content measurement menghubungkan objective, asset, audience, platform, and action. KPI dapat mencakup reach, watch time, retention, saves, shares, click, engaged sessions, qualified leads, assisted conversion, and business outcomes. Content performance perlu dianalisis menurut format, topic, hook, creator, channel, audience, and journey role. Jangan menilai content quality hanya dari view count atau menganggap engagement selalu berdampak ke sales.",
"SIMULATED — video views tinggi tetapi saves, qualified site visits, and brand recall rendah. Konten mungkin menghibur namun tidak memberikan utility atau memperkuat brand association; diagnosis memerlukan objective and audience context.",
["<b>Set objective-specific KPI.</b> Pilih output, attention, engagement, action, or business metric sesuai task.","<b>Tag assets.</b> Gunakan content ID, pillar, hook, format, creator, platform, date, campaign, and CTA.","<b>Analyze patterns.</b> Segment by asset and audience; compare retention, saves, click quality, and conversion.","<b>Translate learning.</b> Tentukan continue, iterate, repurpose, retire, or scale with reason."],
"Buat content performance dashboard schema dan optimization memo untuk 20 assets. Sertakan IDs, format, pillar, retention, engagement, click quality, conversion, objective, and next action.",
[["Mengapa view count bukan universal success metric?","View thresholds/platform definitions berbeda dan tidak membuktikan attention, brand impact, or downstream behavior."],["Apa nilai saves dan shares?","Dapat menunjukkan utility/advocacy, tetapi tetap perlu interpretasi sesuai platform, content type, and business objective."],["Apa yang harus dilakukan bila content metric dan sales tidak sejalan?","Periksa audience/journey role, attribution, landing path, product readiness, and whether asset's intended job is direct conversion."]],[["Watch time","Watch time adalah total durasi video ditonton atau rata-rata durasi per view sesuai definisi platform."],["Retention","Porsi audience yang bertahan sepanjang content."],["Engaged session","Sesi dengan meaningful engagement according to analytics definition."],["Content ID","Identifier unik untuk menghubungkan asset dengan data/report."]],"DPA-T13-CH10"),
G("Content Capstone membangun satu quarter content system dari audience insight hingga measurement. Paket harus menyatukan brand voice, objectives, pillars, editorial architecture, insight mining, storytelling, long/short production, platform adaptation, distribution rights, and optimization. Produksi harus memasukkan shooting, editing, sound, lighting, motion, accessibility, and tool workflow bila role mencakup hands-on creator capability; P3I curriculum menjadi benchmark strategi/editorial/storytelling, bukan bukti semua skill produksi teknis tercakup.",
"SIMULATED — brand meluncurkan produk baru selama 90 hari. Capstone menghasilkan campaign umbrella narrative, editorial calendar, long-form anchor, 12 short assets, creator/community distribution, paid amplification plan, and measurement/learning loop.",
["<b>Frame campaign.</b> Tetapkan audience, positioning, campaign objective, and content role.","<b>Build system.</b> Rancang pillars, editorial calendar, briefs, storytelling, and production workflow.","<b>Ship and distribute.</b> Siapkan assets, rights, platform adaptations, organic/paid/creator/community plans.","<b>Evaluate and iterate.</b> Analisis content quality/performance and update next-quarter strategy."],
"Siapkan content portfolio: audience/insight deck, brand voice, 4–6 pillars, quarter calendar, 3 long-form briefs, 12 short-form storyboards/assets, production specs, distribution/right matrix, dashboard, and optimization review.",
[["Apa yang harus bisa dijelaskan dari content capstone?","Mengapa content themes dipilih, audience need apa yang dijawab, bagaimana diproduksi/disebar, dan bagaimana success diukur."],["Apa yang belum otomatis tercakup oleh kurikulum content strategy?","Practical production depth seperti shooting, editing, lighting, audio, and motion perlu latihan teknis tambahan."],["Bagaimana membuktikan portfolio tanpa client?","Labeli brief/data sebagai simulated; tampilkan storyboard/asset/workflow/source and self-review, bukan fake performance claims."]],[["Editorial system","Editorial system adalah proses perencanaan, produksi, approval, publishing, measurement, dan update konten secara konsisten."],["Storytelling architecture","Struktur hook, tension, narrative, proof, and payoff."],["Production workflow","Production workflow mengatur tahapan briefing, shooting, editing, review, versioning, approval, dan publishing content."],["Content capstone","Sistem content end-to-end yang dapat dipresentasikan."]],"DPA-T13-CH11")
],
kol:[
G("Creator partnerships beroperasi dalam creator economy yang melibatkan talent, agency/MCN, brand, platform, creator manager, affiliate, production, and media amplification. Partnership dapat dibayar untuk reach, content, credibility, community, usage rights, or trackable conversion. Creator partnership bukan sekadar memilih akun dengan followers besar; strategi harus menentukan role creator dalam audience journey dan business objective.",
"SIMULATED — brand memilih creator besar dengan audience tidak relevan. Creator micro memiliki audience category fit dan trust lebih baik. Keputusan harus berdasarkan fit, content quality, geography, engagement quality, cost, and rights.",
["<b>Map ecosystem.</b> Identifikasi creator, manager, agency, MCN, platform, brand, and measurement partners.","<b>Clarify objective.</b> Awareness, education, trust, consideration, content asset, sales, or community.","<b>Choose model.</b> Paid content, seeding, barter, ambassador, affiliate, licensing, or partnership ads.","<b>Define governance.</b> Disclosure, contract, approvals, usage rights, timeline, and measurement."],
"Buat creator ecosystem map dan role matrix untuk awareness, education, product review, conversion, and advocacy campaigns. Sertakan partner types, deliverables, payment model, and risks.",
[["Mengapa creator economy tidak sama dengan follower economy?","Creator economy menilai ekosistem nilai yang dibangun creator melalui kepercayaan, keahlian, komunitas, konten dan hubungan komersial. Follower count hanya satu sinyal jangkauan; brand juga perlu menilai audience fit, kualitas konten, kredibilitas, hak penggunaan dan kontribusi terhadap objective."],["Apa beda influencer campaign dan affiliate partnership?","Influencer partnership dapat membayar produksi, distribusi, expertise atau penggunaan konten sesuai kontrak. Affiliate biasanya mengaitkan kompensasi dengan action yang dapat ditelusuri seperti klik atau penjualan. Satu creator dapat menjalankan keduanya, sehingga fee tetap dan variable commission harus dipisahkan."],["Apa fungsi MCN/creator agency?","MCN atau creator agency dapat membantu talent management, discovery, negosiasi, produksi, administrasi dan hubungan brand. Ruang lingkup berbeda antar organisasi; brand tetap perlu memeriksa siapa pihak kontrak, siapa memiliki authority, biaya perantara dan tanggung jawab deliverables."]],[["Creator economy","Ekosistem creator, platform, partner, monetization, and brand."],["MCN","Multi-Channel Network adalah organisasi yang mengelola atau mendukung sejumlah creator dan channel dalam ekosistem platform video."],["Ambassador","Creator/talent dengan hubungan partnership jangka lebih panjang."],["Partnership model","Bentuk komersial/operasional kerja sama creator."]],"DPA-T14-CH01"),
G("KOL dan KOC adalah pendekatan yang sering dipakai di Indonesia, tetapi keduanya bukan kategori global yang selalu distandarkan. KOL lebih sering dipilih karena expertise/authority/visibility; KOC lebih dekat dengan peer recommendation dan pengalaman pengguna. Nano/micro/macro/mega tiers hanya shortcut; audience relevance, trust, content niche, and quality lebih penting daripada follower threshold semata.",
"SIMULATED — kategori skincare membutuhkan edukasi bahan aktif. Pharmacist creator dapat memberi expertise; micro KOC dapat memberi pengalaman pemakaian sehari-hari. Dua role saling melengkapi, bukan saling menggantikan.",
["<b>Define creator role.</b> Tentukan authority, peer proof, reach, demonstration, content skill, or conversion role.","<b>Segment by tier/niche.</b> Catat audience size, geo, topic, language, and audience composition.","<b>Choose portfolio mix.</b> Seimbangkan creator tier, niche, audience overlap, content formats, and budget.","<b>Disclose clearly.</b> Terapkan advertising disclosure and platform/regulatory requirements."],
"Buat KOL/KOC creator matrix berisi 20 creators synthetic/example: tier, niche, audience geo, trust signal, content format, objective fit, rate range assumption, disclosure, and recommended role.",[["Apa beda KOL dan KOC secara praktis?","KOL biasanya diposisikan berdasarkan expertise, authority atau pengaruh pada kategori; KOC lebih menekankan pengalaman dan peer recommendation. Istilah ini merupakan label praktik yang batasnya tidak selalu konsisten. Pilih creator berdasarkan fungsi, kredibilitas dan audience, bukan label semata."],["Mengapa tier berdasarkan followers tidak cukup?","Follower tier hanya mengelompokkan ukuran audience berdasarkan ambang yang dapat berbeda menurut platform, negara dan kategori. Tier tidak membuktikan relevansi, authenticity, trust, kemampuan bercerita atau kualitas interaksi. Bandingkan native insights, audience composition, content sample dan objective fit."],["Apa kewajiban disclosure?","Disclosure harus membuat hubungan komersial mudah dikenali, termasuk pembayaran, sponsor, gifted product atau affiliate ketika ketentuan berlaku. Terapkan hukum dan pedoman iklan Indonesia serta pengaturan disclosure masing-masing platform; catat siapa bertanggung jawab dan periksa sebelum konten dipublikasikan."]],
[["KOL","Key Opinion Leader; creator/expert dengan authority pada area."],["KOC","Key Opinion Consumer; peer/user recommendation orientation."],["Nano/Micro/Macro","Kategori ukuran creator yang batasnya dapat berbeda."],["Disclosure","Pemberitahuan transparan tentang hubungan komersial."]],"DPA-T14-CH02"),
G("Creator discovery menggunakan criteria yang dapat direplikasi: category fit, audience demographics/geography, engagement quality, content quality, brand safety, previous sponsorship, follower growth anomalies, and commercial availability. Discovery sources dapat berupa platform search, creator marketplace, agency roster, social listening, and referrals. Shortlist tidak boleh hanya berdasarkan popularitas; semua claims tentang audience harus diverifikasi dengan available analytics atau media kit.",
"SIMULATED — 50 creator candidates ditemukan; 10 punya audience overlap tinggi, lima memiliki fake engagement signals, dan tiga punya competitor exclusivity. Discovery matrix memisahkan eligibility dari creative fit.",
["<b>Define criteria.</b> Buat must-have and nice-to-have filters sesuai objective.","<b>Search systematically.</b> Gunakan platform/marketplace, hashtags, competitor mentions, and creator network.","<b>Build shortlist.</b> Catat profile, audience, content, geo, brand history, rate source, contact, and fit score.","<b>Validate with creator/agency.</b> Minta media kit, insights proof, availability, exclusivity, and current terms."],
"Buat discovery workbook 30 candidates dan shortlist lima: criteria, source, profile, audience evidence, content fit, conflicts, outreach status, and recommendation.",[["Mengapa discovery perlu source trail?","Source trail mencatat kapan creator ditemukan, kanal penemuan, URL/profile, screenshot atau export, sumber audience data, kontak dan tanggal verifikasi. Jejak ini memungkinkan tim menguji ulang perubahan follower, rate, availability dan brand history sebelum shortlist, approval atau kontrak."],["Apa beda fit score dan performance guarantee?","Fit score adalah alat pembanding berbobot untuk audience, content, category, geography, credibility, risk dan cost. Skor membantu shortlist, tetapi bergantung pada kriteria, data dan bobot yang dipilih; ia bukan forecast, service-level commitment atau jaminan campaign outcome."],["Apa yang harus dikonfirmasi sebelum shortlist final?","Sebelum shortlist final, verifikasi audience evidence dan tanggalnya, content fit, recent sponsorship, competitor conflict, availability, deliverables, fee basis, payment terms, disclosure, usage rights dan paid amplification permission. Minta bukti native analytics atau media kit, lalu dokumentasikan data yang belum tersedia."]],[["Creator discovery","Proses menemukan talent yang sesuai objective."],["Media kit","Dokumen creator tentang audience, reach, formats, rates, and past work."],["Audience overlap","Audience overlap mengukur kesamaan audience yang mengikuti atau terpapar beberapa creator maupun platform."],["Conflict check","Pemeriksaan competitor category, exclusivity, and brand suitability."]],"DPA-T14-CH03"),
G("Creator vetting memeriksa authentic audience, engagement quality, content credibility, brand safety, previous sponsorship, follower growth anomalies, and category fit. Fraud indicators bukan bukti final; sudden spikes, generic comments, bot-like profiles, engagement pods, and inconsistent geo perlu investigasi. Gunakan third-party tools sebagai signal, bukan verdict tunggal. Simpan evidence dan decision rationale.",
"SIMULATED — creator memiliki ER tinggi tetapi comments berulang, geo mismatch, and follower spike dari giveaway. Vetter harus meminta native insights, recent audience breakdown, and campaign-specific proof before approval.",
["<b>Audit audience.</b> Cek geography, age, interests, followers trend, and platform analytics where available.","<b>Review engagement.</b> Baca comment quality, saves/shares, engagement consistency, and suspicious patterns.","<b>Assess content/brand safety.</b> Review recent posts, claims, disclosure, controversies, and competitor conflicts.","<b>Record confidence.</b> Catat evidence, tool limits, flags, follow-up questions, and approval status."],
"Buat creator vetting scorecard untuk lima candidates dengan audience fit, ER context, quality, fake signal checks, brand safety, history, and accept/reject/risk decision.",
[["Apakah suspicious follower growth pasti fraud?","Lonjakan follower dapat berasal dari viral content, media coverage, campaign, giveaway atau perubahan platform, selain aktivitas tidak autentik. Anggap pola tersebut sebagai risk signal, bukan bukti fraud. Periksa periode, sumber pertumbuhan, audience geography, engagement quality dan penjelasan creator."],["Mengapa engagement rate saja tidak cukup?","Engagement rate merangkum interaksi menurut denominator tertentu, tetapi tidak menunjukkan kualitas atau relevansi setiap interaksi. Periksa komentar, saves, shares, audience geography, paid activity, format dan periode; definisi metrik berbeda antar platform sehingga perbandingan harus dinormalisasi."],["Apa bukti vetting yang harus disimpan?","Simpan dated profile capture, native insight export atau media kit, sumber dan tanggal data, growth/engagement flags, content review, creator clarification, competitor checks, risk rating, reviewer dan approval rationale. Catat keterbatasan tool; jangan menyimpan data personal berlebihan atau melampaui tujuan."]],[["Engagement quality","Kualitas interaksi, bukan hanya jumlah likes/comments."],["Audience authenticity","Audience authenticity menilai apakah audience signals mencerminkan pengguna nyata dan relevan, bukan aktivitas palsu atau manipulatif."],["Fraud screening","Pemeriksaan pola/indikator engagement atau audience tidak valid."],["Brand suitability","Kesesuaian creator/content dengan nilai dan toleransi brand."]],"DPA-T14-CH04"),
G("Influencer strategy menerjemahkan objective menjadi creator roles, tier mix, campaign concept, timeline, budget, and KPI. Campaign brief perlu menjelaskan audience, insight, message, content role, deliverables, creative freedom, mandatories, CTA, disclosure, and usage rights. Creator plan harus memperhitungkan audience overlap, product availability, seasonality, production capacity, and cross-channel amplification.",
"SIMULATED — campaign launch memakai 2 authority creators untuk education, 8 micro creators untuk social proof, and 30 KOCs untuk trial stories. Tujuan dan KPI berbeda per tier, bukan seluruhnya dinilai dari reach.",
["<b>Map objective-to-creator role.</b> Tentukan awareness/education/proof/content asset/conversion needs.","<b>Build tier and budget mix.</b> Hitung fee, production, seeding, usage rights, amplification, agency, and contingencies.","<b>Set campaign architecture.</b> Timeline, wave, deliverables, platform, CTA, and reporting.","<b>Set KPI and guardrails.</b> Reach/quality, views/retention, engagement, qualified traffic, conversion, disclosure, and brand safety."],
"Buat creator campaign plan 4 minggu: creator tier mix, shortlists, budget, message, timeline, deliverables, KPI, rights, disclosure, and amplification. Buat base/conservative scenarios.",[["Mengapa KPI harus berbeda per creator role?","Creator authority atau education dapat dinilai dari credibility, comprehension dan qualified consideration; creator reach dari reach serta view quality; UGC dari usable assets; affiliate dari tracked actions dan sales. Tetapkan KPI sesuai role dan jangan menilai seluruh creator hanya dari views atau engagement."],["Apa risiko audience overlap tinggi?","Audience overlap tinggi berarti beberapa creator berpotensi menjangkau orang yang sama. Reach tambahan dari creator berikutnya dapat menurun, tetapi overlap juga dapat memperkuat frequency atau pesan. Evaluasi deduplicated reach bila tersedia, objective, incremental cost dan keterbatasan metode."],["Apa yang harus masuk budget creator?","Budget harus memuat talent fee, production, seeding/product cost, packing dan shipping, agency fee, usage rights, exclusivity, paid amplification, measurement, tax yang berlaku dan contingency. Pisahkan fixed dan variable cost, tandai asumsi synthetic, serta jangan mengasumsikan rate pasar tanpa quotation aktual."]],[["Creator mix","Creator mix adalah komposisi creator berdasarkan tier, role, audience, format, dan kontribusi yang diharapkan."],["Deliverable","Output kerja yang wajib diserahkan."],["Usage rights","Izin penggunaan/whitelisting selama scope/durasi tertentu."],["Amplification","Paid/partner distribution tambahan dari asset creator."]],"DPA-T14-CH05"),
G("KOL brief harus memberi strategic direction tetapi tidak membunuh creator authenticity. Brief memuat campaign context, audience, product truth, key message, proof, do/don't, story role, platform/format, deliverables, CTA, disclosure, mandatory, and approval. Storyline harus menunjukkan pengalaman atau explanation yang believable. Approval flow membutuhkan SLA dan batas revisi agar creator autonomy dan brand safety seimbang.",
"SIMULATED — brief meminta creator mengatakan 'nomor satu paling aman' tanpa evidence. Creator tidak boleh dipaksa membuat unsupported claim; ganti dengan demonstrasi faktual atau approved proof.",
["<b>Brief the why.</b> Jelaskan audience, problem, objective, proposition, and creator role.","<b>Define guardrails.</b> Product facts, prohibited claims, disclosure, legal wording, mandatory assets, and safety.","<b>Co-create storyline.</b> Set hook, scenes, proof, CTA, and creator-native execution.","<b>Manage approval.</b> Draft/review/revise/final, SLA, version, and publication confirmation."],
"Buat creator brief, storyline outline, key-message/proof matrix, do/don't, disclosure copy, approval workflow, and feedback template for one campaign.",[["Apa risiko brief terlalu preskriptif?","Brief yang terlalu preskriptif mengatur terlalu banyak dialog, scene dan ekspresi sehingga creator kehilangan suara serta cara komunikasi yang dipercaya audience. Beri objective, facts, mandatory, prohibited claims dan guardrails; biarkan creator menentukan eksekusi yang tetap sesuai strategi."],["Apa risiko brief terlalu bebas?","Brief yang terlalu bebas tanpa product facts, claim boundaries, mandatory, disclosure, audience dan approval path dapat menghasilkan pesan menyesatkan atau tidak sesuai kontrak. Berikan ruang kreatif di dalam guardrails yang jelas, termasuk bukti claim, prohibited statements dan escalation owner."],["Bagaimana approval SLA membantu?","Approval SLA menjelaskan siapa meninjau, tenggat feedback, jumlah revisi, format final dan batas waktu sign-off. SLA mengurangi keterlambatan, mencegah feedback yang bertentangan dan memberi creator kepastian kapan aset dapat dipublikasikan sesuai kontrak dan platform schedule."]],[["Creator brief","Arahan campaign dan deliverables bagi creator."],["Storyline","Urutan narasi/scene yang menyampaikan message."],["Mandatory","Elemen wajib termasuk claim, tag, CTA, and disclosure."],["Approval SLA","Approval SLA menetapkan batas waktu review dan feedback agar produksi serta publishing tidak tertunda."]],"DPA-T14-CH06"),
G("Negotiation dan contract mengikat scope, fee, deliverables, payment terms, usage rights, exclusivity, whitelisting, revisions, cancellations, disclosure, performance claims, IP, confidentiality, and remedies. Creator fee tidak otomatis mencakup perpetual paid usage. Buyer harus memisahkan organic posting license, paid amplification, raw footage, cutdowns, edit, territory, channels, and duration.",
"SIMULATED — fee Rp15 juta mencakup satu video organic post selama 30 hari, tetapi brand mengasumsikan hak memakai video di ads selama 12 bulan. Perlu addendum usage rights dan negotiated fee.",
["<b>Normalize rate.</b> Bandingkan format, length, platform, follower/engagement context, production, and deliverables.","<b>Negotiate scope.</b> Tetapkan revisions, deadline, payment, cancellation, and KPI reporting.","<b>License rights.</b> Catat channel, territory, duration, paid/organic, edits, raw files, likeness, music, and exclusivity.","<b>Contract and approval.</b> Escalate legal terms, sign, archive, and schedule renewal/expiry alerts."],
"Buat creator deal sheet dan contract checklist dengan rate, deliverables, revisions, usage rights, paid whitelisting, exclusivity, disclosure, cancel, payment, and expiry fields.",
[["Apa beda organic posting rights dan paid usage rights?","Organic posting rights mengatur publikasi pada akun creator sesuai scope perjanjian. Paid usage rights memberi brand izin tambahan untuk memakai atau mengamplifikasi asset melalui iklan, channel, territory dan periode tertentu. Satu izin tidak otomatis mencakup hak yang lain."],["Mengapa raw footage harus disebutkan?","Raw footage menentukan hak atas file sumber, akses, storage, editing, cutdowns, derivative works, approval dan reuse setelah campaign. Kontrak perlu menyatakan apakah file diserahkan, siapa memegang hak, batas modifikasi, channel, territory, durasi serta biaya tambahan."],["Apa yang dilakukan bila creator meminta exclusivity luas?","Negosiasikan exclusivity dengan mendefinisikan kategori produk, daftar competitor, territory, channel dan periode. Periksa dampaknya terhadap peluang kerja creator dan nilai brand, lalu tukarkan pembatasan yang lebih luas dengan kompensasi yang proporsional serta tanggal berakhir yang tegas."]],
[["Usage rights","Izin penggunaan content/persona pada channel/periode tertentu."],["Exclusivity","Pembatasan kerja sama dengan competitor/category."],["Whitelisting","Authorization menjalankan ads melalui creator/partner identity."],["Deliverable schedule","Jadwal output, review, and publication."]],"DPA-T14-CH07"),
G("Seeding dan barter membangun trial/relationship tetapi bukan gratis: product cost, packaging, shipping, staff time, and content rights tetap ada. Seeding harus punya target, reason, opt-in, logistics, brief, and post-send follow-up. Barter harus menyebut deliverables atau menyatakan tidak ada guarantee. Relationship management meliputi CRM creator, communication, feedback, payment, and long-term trust.",
"SIMULATED — 100 products dikirim tanpa creator selection/permission. Hasil content rendah dan biaya shipping terbuang. Pilot seeding yang lebih tepat memilih audience/fit, memperoleh consent to receive product, and sets expectation honestly.",
["<b>Define seeding objective.</b> Trial, review, content asset, feedback, relationship, or event invite.","<b>Select and consent.</b> Vet audience fit, confirm address/permission, and clarify no-guarantee vs deliverables.","<b>Manage logistics.</b> Track SKU, package, dispatch, delivery, product safety, and contact owner.","<b>Maintain relationship.</b> Follow up respectfully, log content/feedback, rights, and next collaboration."],
"Buat seeding program plan 30 creators: selection criteria, opt-in, product allocation, logistics tracker, expected/non-guaranteed outputs, feedback form, and cost model.",[["Apakah gifting otomatis mewajibkan posting?","Pengiriman produk tanpa persetujuan kontraktual tidak dengan sendirinya menciptakan kewajiban publikasi. Bedakan gifting tanpa deliverable, barter dengan output tertentu dan paid collaboration; jelaskan expectation, disclosure, rights dan kompensasi secara tertulis sebelum creator menyetujui."],["Mengapa opt-in penting?","Opt-in memastikan creator memahami tujuan pengiriman, produk, data alamat yang digunakan, ekspektasi, batas komunikasi dan apakah ada deliverable. Persetujuan menerima produk tidak boleh diperlakukan sebagai persetujuan otomatis untuk posting, paid usage atau pemrosesan data di luar tujuan."],["Apa biaya seeding selain produk?","Biaya seeding meliputi nilai produk, packaging, fulfillment, shipping, pajak/biaya relevan, handling, staff time, damaged/returned goods dan follow-up. Bila brand meminta konten atau hak penggunaan, masukkan fee serta lisensi terpisah; jangan mengasumsikan gifting menghasilkan asset gratis."]],
[["Seeding","Pengiriman produk kepada creator untuk trial/relationship."],["Barter","Pertukaran produk/jasa dengan deliverables sesuai perjanjian."],["Opt-in","Persetujuan pihak untuk mengikuti aktivitas."],["Creator CRM","Catatan hubungan, preferences, performance, rights, and history creator."]],"DPA-T14-CH08"),
G("Campaign execution mengatur production, deadlines, asset collection, quality review, disclosure, platform settings, link/tag, publishing, and proof. Deliverable acceptance harus didasarkan pada contract/brief, bukan selera internal setelah tayang. Tanggal post, URL, screenshot, view/engagement snapshots, and invoice status perlu dicatat. Crisis/negative feedback harus memiliki escalation protocol.",
"SIMULATED — creator publish video dengan wrong product link dan disclosure tertinggal. Team perlu detect cepat, request correction, preserve evidence, and document whether paid boosting should pause.",
["<b>Run production calendar.</b> Monitor draft, shoot, review, revisions, final export, and publishing deadline.","<b>QA content.</b> Cek claim, product, disclosure, audio/music rights, brand safety, CTA, link, and specs.","<b>Confirm publishing.</b> Record URL, timestamp, asset version, platform, and screenshot.","<b>Manage issues.</b> Set incident severity, escalation, correction/takedown, and stakeholder update."],
"Buat execution tracker untuk 10 creator posts: status, owner, due date, asset version, approval, disclosure, URL, proof, corrections, invoice, and final acceptance.",[["Apa yang dilakukan jika creator telat publish?","Periksa deadline dan remedy dalam kontrak, lalu konfirmasi status kepada creator/agency serta nilai dampak terhadap campaign calendar. Dokumentasikan keterlambatan dan keputusan: reschedule, revised deliverable, replacement atau remedy yang disepakati. Jangan mengubah fee atau melakukan penalti di luar terms yang berlaku."],["Mengapa screenshot alone tidak cukup untuk proof?","Screenshot dapat menunjukkan tampilan konten, tetapi tidak selalu membuktikan URL, waktu publikasi, asset version, disclosure atau insight final. Simpan permalink, timestamp, account/platform, capture, export native analytics, approval history dan permission record sesuai deliverable serta contract."],["Apa yang harus ditangani segera setelah salah link?","Hentikan atau pause amplification bila destination salah, perbaiki link dan tracking, lalu beri tahu creator, agency serta campaign owner. Catat periode dan dampak, simpan bukti, verifikasi landing page serta disclosure, dan lanjutkan hanya setelah pihak berwenang mengonfirmasi koreksi."]],
[["Content delivery","Penyerahan aset sesuai brief dan contract."],["Proof of publication","Bukti asset tayang pada platform dan waktu tertentu."],["Incident escalation","Proses menaikkan issue ke owner/tim keputusan."],["Acceptance criteria","Kriteria formal untuk menerima deliverable."]],"DPA-T14-CH09"),
G("Paid amplification dan Partnership Ads memakai creator identity/content untuk distribution berbayar. Boosting dari brand page berbeda dari partnership ad/whitelisting. Campaign setup perlu account permission, post authorization, ad disclosure, creative rights, targeting, budget, tracking, and expiry. Organic creator performance dan paid amplified performance harus dilaporkan terpisah sebelum digabung ke total campaign view.",
"SIMULATED — post creator memiliki organic engagement baik tetapi partnership ad ditolak karena authorization expiry dan missing permission. Paid rights/access harus dipastikan sebelum media schedule.",
["<b>Confirm permission.</b> Cek creator/brand account, authorized post, ad account, duration, and revocation.","<b>Prepare paid setup.</b> Tentukan objective, audience, placements, budget, destination, tracking, and creative edits.","<b>Monitor separately.</b> Pisahkan organic metrics dari paid reach/spend/conversion.","<b>Check rights and policy.</b> Validate music, captions, disclosures, usage duration, and account permissions."],
"Buat partnership ads checklist dan paid amplification plan untuk dua creator assets. Sertakan permissions, rights, objective, budget, tracking, organic/paid reporting, and expiry alerts.",[["Apa beda boost dan partnership ad?","Boosting biasanya mempromosikan post melalui kontrol akun/brand sesuai fitur platform. Partnership Ads menggunakan creator atau partner identity dan memerlukan authorization sesuai platform. Detail setup berbeda: Meta memakai partnership permission, sedangkan TikTok Spark Ads memerlukan otorisasi post/creator."],["Mengapa organic and paid metrics harus dipisah?","Paid spend menambah distribusi dan dapat mengubah audience, reach, frequency serta hasil delivery. Pisahkan organic reach/views/engagement dari paid delivery dan spend, lalu tampilkan total secara terpisah atau sebagai gabungan berlabel. Jangan mengatribusikan seluruh outcome ke organic creator activity."],["Apa risiko permission expiry?","Authorization memiliki scope dan masa berlaku yang ditentukan platform atau persetujuan creator. Saat permission berakhir atau dicabut, iklan dapat berhenti, tidak dapat diperpanjang atau kehilangan dasar penggunaan identity/content. Catat expiry dan peroleh authorization baru sebelum melanjutkan paid use."]],
[["Partnership Ads","Format iklan yang menggunakan creator/partner identity dengan permission."],["Whitelisting","Authorization menjalankan ads melalui creator/partner identity."],["Amplification","Distribusi tambahan melalui paid media."],["Authorization expiry","Batas waktu permission untuk akses/advertising."]],"DPA-T14-CH10"),
G("Influencer measurement harus mencocokkan KPI dengan creator role: awareness (reach/unique, view quality), engagement (saves/shares/comments), content quality, traffic, lead/sales, and advocacy. Attribution dipengaruhi codes/links, platform windows, view-through, and overlap. Cost metrics seperti CPM/CPE/CPV perlu denominator dan format yang sesuai. ROI harus mempertimbangkan fee, production, rights, seeding, amplification, discounts, and margin.",
"SIMULATED — campaign report mencatat 5 juta views, tetapi 80% dari paid amplification dan sedikit qualified visits. Executive tidak boleh mengklaim creator organic reach mencapai 5 juta; report perlu memisahkan sources dan downstream outcomes.",
["<b>Define role-based KPIs.</b> Tetapkan metrics untuk reach, attention, trust, traffic, conversion, or content asset value.","<b>Tag creator activity.</b> Gunakan UTM, codes, content IDs, platform reports, and campaign windows.","<b>Reconcile cost.</b> Masukkan fees, production, seeding, rights, media, discount, and net revenue/margin.","<b>Interpret carefully.</b> Pisahkan correlation/attribution/assisted role dan jelaskan incrementality limitations."],
"Buat influencer dashboard/memo untuk 10 creator: fee, organic/paid reach, views/retention, engagement quality, clicks, conversions, cost metrics, margin assumptions, and recommendations.",[["Mengapa total views tidak boleh diklaim seluruhnya organic?","Total views dapat menggabungkan organic views dan views dari paid amplification, tergantung definisi pelaporan platform. Pisahkan source of delivery dan periode; klaim organic harus menggunakan metrik yang memang mengukur organic distribution, bukan angka total campaign tanpa segmentasi."],["Apa risiko discount code sebagai attribution tunggal?","Discount code hanya menangkap transaksi yang memakai kode tersebut dan dapat dibagikan di luar audience awal. Pembelian tanpa kode, view-through, overlap dan baseline demand tidak tercakup. Gunakan kode bersama UTM, platform insight, CRM dan desain incrementality bila perlu mengestimasi causal impact."],["Apa yang harus masuk ROI?","ROI perlu menggunakan denominator biaya yang konsisten: talent fee, agency, production, seeding, shipping, usage rights, paid media, discounts, measurement dan biaya variabel lain. Hubungkan dengan net revenue atau contribution margin, bukan gross sales saja, lalu jelaskan attribution window serta assumptions."]],[["CPM","Cost per thousand impressions menunjukkan biaya untuk setiap seribu impressions pada basis delivery yang disepakati."],["CPE","Cost per engagement menurut definisi action."],["CPV","Cost per view sesuai platform/view threshold."],["Influencer attribution","Credit/measurement atas outcome terkait creator touchpoints."]],"DPA-T14-CH11"),
G("Creator Partnerships Capstone menunjukkan proses lengkap dari discovery hingga measurement dan relationship management. Portfolio harus mencakup strategy, creator matrix, vetting evidence, brief, deal/rights, seeding/production, execution tracker, partnership ads, reporting, and post-campaign review. Semua creator examples dan results yang bukan campaign aktual diberi label SIMULATED; no invented endorsements.",
"SIMULATED — brand consumer menyiapkan creator launch wave dengan authority/KOL, micro creators, and KOC seeding. Capstone menguji objective fit, rights, production, disclosure, amplification, and commercial reporting.",
["<b>Plan program.</b> Set audience, objectives, creator roles, tier mix, budget, timeline, and KPIs.","<b>Recruit and contract.</b> Vet, shortlist, negotiate, license, and onboard creators.","<b>Execute and amplify.</b> Deliver assets, QA, publish, track, and activate paid rights.","<b>Measure and retain.</b> Reconcile results/cost, document learning, and update creator relationship database."],
"Bangun capstone pack: creator strategy, 20-name shortlist, vetting scorecard, budget, creative brief, contract/rights matrix, seeding/production tracker, partnership ads plan, performance dashboard, and executive recommendation.",
[["Apa bukti capstone siap portfolio?","Portfolio evidence harus menunjukkan alur strategy, discovery, vetting, briefing, contract/rights, disclosure, execution, paid activation, tracking dan reporting. Sertakan file kerja serta source trail. Bila campaign dibuat untuk latihan, tandai seluruh creator, result dan assumptions sebagai SIMULATED."],["Bagaimana membuktikan creator selection berbasis data?","Tunjukkan audience evidence bertanggal, content sample, fit criteria dan weighting, vetting/risk review, fee source, rights, availability serta alasan memilih creator dibanding alternatif. Labeli data yang belum diverifikasi; jangan mengarang audience analytics, rate market atau performance result."],["Apa yang membedakan campaign report dari relationship review?","Campaign report menilai deliverables, delivery, reach, engagement, traffic, outcome dan cost pada campaign tertentu. Relationship review menilai komunikasi, reliability, collaboration, claim/disclosure compliance, rights management, issue handling dan future fit. Keduanya saling melengkapi tetapi menjawab keputusan yang berbeda."]],[["Creator partnership capstone","Kasus end-to-end discovery, deal, execution, and measurement."],["Rights matrix","Rights matrix merangkum channel, territory, duration, format, editing, paid usage, dan license scope creator asset."],["Creator scorecard","Perbandingan creator berdasarkan objective fit and quality."],["Partnership review","Evaluasi hasil dan kualitas hubungan creator."]],"DPA-T14-CH12")
],
affiliate:[
G("Affiliate marketing membayar partner berdasarkan action/conversion yang ditetapkan. Ecosystem dapat melibatkan advertiser, affiliate network/platform, publisher, creator affiliate, sub-network, tracking provider, and finance. Performance terms harus menjelaskan eligible action, attribution window, commission basis, validation, reversal, fraud, payout, and margin. Affiliate bukan sinonim influencer; creator dapat berperan sebagai affiliate bila commercial model menekankan tracked sale/commission.",
"SIMULATED — publisher coupon menghasilkan banyak attributed orders, tetapi sebagian menggunakan voucher yang akan dipakai customer existing. Program harus membedakan incremental acquisition, existing demand capture, attribution leakage, and commission economics.",
["<b>Map participants.</b> Catat advertiser, affiliate platform/network, publisher/creator, tracking, and finance.","<b>Define conversion.</b> Tetapkan eligible order/lead, validation, attribution, window, and exclusions.","<b>Set commercial model.</b> Pilih CPS/CPA/CPL/hybrid dengan margin and payout guardrails.","<b>Govern program.</b> Tetapkan partner policies, disclosure, fraud controls, and payment reconciliation."],
"Buat affiliate ecosystem and program brief untuk brand: partner types, conversion definition, tracking flow, attribution window, commission model, fraud rules, and payout governance.",
[["Apa beda affiliate dengan influencer marketing?","Influencer sering dibayar untuk reach/content/engagement; affiliate dibayar menurut tracked action/sales sesuai contract."],["Mengapa conversion definition harus jelas?","Menentukan apakah order/lead eligible, kapan divalidasi, kapan komisi reversal, and kapan dibayar."],["Apa risiko coupon attribution?","Code leakage, last-click capture, cannibalization, and existing-customer credit dapat membayar komisi untuk sale non-incremental."]],
[["Advertiser","Pihak brand yang membiayai program affiliate."],["Publisher","Partner yang mempromosikan offer melalui media/content."],["CPS","Cost per Sale commission model."],["Eligible conversion","Action yang memenuhi contract/program rules."]],"DPA-T15-CH01"),
G("Publisher and creator affiliate memiliki model traffic and content berbeda. Publisher dapat berupa content/review, comparison, coupon, cashback, loyalty, search arbitrage, and sub-network. Creator affiliate memakai short video/live/showcase, product link, or platform-native commission. Recruitment harus menilai audience fit, traffic source, content method, disclosure, conversion quality, and policy risk.",
"SIMULATED — cashback publisher mendorong last-click conversions tetapi profit rendah; niche content publisher memberi conversion lebih sedikit dengan new-to-brand share lebih tinggi. Mix harus dinilai berdasarkan contribution and incrementality.",
["<b>Classify partner type.</b> Kelompokkan content, coupon, cashback, loyalty, creator, media buyer, and sub-network.","<b>Validate traffic.</b> Tanyakan source, placement, promotion methods, geo, audience, and incentive use.","<b>Set partner terms.</b> Tentukan allowed tactics, search bidding rules, brand terms, disclosure, and prohibited methods.","<b>Track quality.</b> Monitor new-to-brand, returns, order value, cancellation, and commission exposure."],
"Buat publisher classification and recruitment matrix: partner type, audience/source, allowed method, risk, traffic quality evidence, commission fit, and onboarding need.",[["Mengapa partner type penting?","Setiap tipe partner membawa pola traffic, attribution, fraud, audience, dan commission yang berbeda sehingga kontrol serta KPI harus disesuaikan."],["Apa risiko sub-network yang tidak transparan?","Traffic source and downstream publishers sulit diaudit; fraud or policy violations may be hidden."],["Bagaimana membedakan creator affiliate dari paid creator?","Creator affiliate earns commission per tracked action; paid creator receives fee for content/reach, or may combine both under separate terms."]],
[["Coupon publisher","Partner yang mempromosikan voucher/discount codes."],["Cashback publisher","Partner yang memberi reward kepada pembeli."],["Sub-network","Network yang menyalurkan traffic lewat publisher lain."],["Creator affiliate","Creator yang menerima komisi atas tracked conversions."]],"DPA-T15-CH02"),
G("Partner discovery and recruitment harus memiliki ideal partner profile, category fit, reach/source quality, content standards, commercial expectations, and compliance checks. Outreach menjelaskan value proposition untuk partner, tracking, support, payment, asset, and exclusivity. Recruitment bukan mengejar jumlah partner; active/productive partner ratio dan incremental contribution lebih relevan.",
"SIMULATED — program onboard 500 publishers tetapi hanya 20 aktif dan beberapa melanggar brand terms. Lebih baik merekrut 50 partners yang relevan dengan onboarding, support, and quality controls.",
["<b>Define partner ICP.</b> Tetapkan category, traffic, geo, audience, content type, and allowed promotion.","<b>Research and prioritize.</b> Cari partner dari network/creator/content ecosystem dan score fit/risk.","<b>Outreach and onboard.</b> Jelaskan offer, commission, tracking, payout, assets, disclosure, and support.","<b>Activate partners.</b> Beri first campaign, monitor first conversions, and review quality before scaling."],
"Buat recruitment pipeline untuk 30 partner prospects: source, type, audience, reach, fit, risks, contact, status, onboarding requirements, and activation target.",[["Apa beda partner recruited dan partner activated?","Recruited berarti partner telah bergabung; activated berarti partner sudah mempromosikan offer atau menghasilkan eligible activity."],["Mengapa first-conversion review penting?","Review conversion awal membantu mendeteksi poor traffic, fraud, atau setup error sebelum partner diberi volume lebih besar."],["Apa yang perlu ada di partner kit?","Offer, product feed/assets, tracking links, commission terms, rules, disclosure, contact, and troubleshooting."]],[["Partner ICP","Ideal Partner Profile untuk program."],["Activation","Activation terjadi ketika partner mulai mempromosikan offer atau menghasilkan aktivitas yang memenuhi kriteria program."],["Partner kit","Asset dan informasi operasional untuk publisher."],["Partner pipeline","Tahapan sourcing hingga productive partnership."]],"DPA-T15-CH03"),
G("Commission models meliputi CPS, CPA, CPL, hybrid, tiered, fixed fee, bonus, and performance incentives. Commission harus diuji terhadap gross margin, discount, returns, tax, fulfilment, marketplace fees, and existing customer behavior. Tiered incentives dapat meningkatkan volume tetapi mendorong low-quality conversions. Payout terms, validation, reversal, cap, and effective dates harus tercatat.",
"SIMULATED — produk memiliki contribution margin 25%. Commission 20% dari gross sales ditambah voucher 10% dapat membuat contribution negative setelah fees/returns. Program harus menghitung allowable commission berdasarkan eligible net value.",
["<b>Define commission basis.</b> Gross/net sales, pre/post discount, shipped/paid order, and refund policy.","<b>Model unit economics.</b> Hitung product margin, fulfillment, payment/platform fee, discount, commission, and contribution.","<b>Design incentives.</b> Set tier thresholds, quality gates, cap, bonus period, and eligible action.","<b>Document payout rules.</b> Validation, reversal, tax, payment cycle, currency, and dispute process."],
"Buat commission calculator untuk CPS/CPA/hybrid dengan sensitivity: AOV, margin, discount, refund, fee, commission, and allowable acquisition cost. Labeli assumptions.",[["Mengapa komisi tidak sebaiknya berdasarkan gross sales tanpa caveat?","Discount, cancellations, returns, taxes, and fees dapat mengurangi net value; gross basis dapat membuat program rugi."],["Apa fungsi reversal/clawback?","Menarik kembali atau membatalkan commission untuk invalid, cancelled, returned, or non-eligible conversions."],["Bagaimana tiered incentive dapat menimbulkan risiko?","Partner dapat mengejar volume berkualitas rendah atau fraud ketika mendekati bonus threshold, sehingga perlu quality guardrails dan audit."]],[["CPS","Commission per sale adalah komisi yang dibayarkan untuk setiap penjualan valid sesuai rules program."],["CPA","Cost per action atau commission per action adalah biaya atau komisi untuk action yang didefinisikan dalam program."],["Hybrid commission","Hybrid commission menggabungkan fixed fee, variable payment, dan/atau performance commission dalam satu skema kompensasi."],["Clawback","Pengembalian commission untuk conversion yang tidak eligible."]],"DPA-T15-CH04"),
G("Affiliate platforms, product feeds, and tracking tools menghubungkan offer, SKU, deep links, attribution, publisher IDs, coupon codes, and conversion records. Product feeds membutuhkan title, price, availability, image, link, category, and update schedule. Deep links harus membuka product/app target dengan tracking intact. Platform access and available products differ by marketplace, country, seller, and program status; always verify current provider documentation.",
"SIMULATED — product feed masih menampilkan harga lama dan SKU out of stock. Affiliate content tetap mengirim traffic ke item tidak tersedia; feed sync and stock suppression perlu diaktifkan.",
["<b>Inspect feed schema.</b> Validate IDs, titles, images, price, stock, category, URL, and update frequency.","<b>Configure tracking.</b> Set publisher ID, sub-ID, click ID, deep links, coupons, conversion event, and consent.","<b>Test end-to-end.</b> Click link, open destination, verify parameters, purchase/lead, and postback/report record.","<b>Monitor feed health.</b> Track rejected products, stale price, stock-out, broken URL, and mapping errors."],
"Buat product feed data dictionary, deep-link/tracking map, and QA cases for five SKUs. Verify price, availability, image, destination, IDs, publisher attribution, and update cadence.",[["Apa risiko stale product feed?","Feed yang usang dapat menampilkan harga salah atau produk tidak tersedia, merusak conversion, customer trust, dan partner relationship."],["Apa fungsi sub-ID?","Sub-ID memisahkan publisher placement, campaign, atau creator source agar attribution, reporting, dan commission reconciliation lebih rinci."],["Mengapa deep link perlu test di app dan web?","Redirect dan tracking dapat gagal pada kondisi device, app installation, atau browser berbeda; uji semua jalur sebelum campaign live."]],
[["Product feed","File/API data produk untuk platform/publisher."],["Deep link","URL yang membuka halaman/app/product spesifik."],["Sub-ID","Parameter untuk membedakan placement/source dalam partner tracking."],["Postback","Server notification tentang conversion ke tracking platform."]],"DPA-T15-CH05"),
G("Tracking links and attribution menentukan bagaimana click dan conversions dipasangkan dengan publisher. Cookie loss, cross-device, browser restrictions, app/web, redirects, coupon leakage, last-click overwrites, and attribution windows dapat mengubah credit. Affiliate analyst harus memahami click ID, sub-ID, conversion IDs, dedupe, view/click rules, validation, and source of truth. Jangan menganggap attribution credit berarti incremental sale.",
"SIMULATED — user click creator affiliate link, kemudian mencari brand di Google dan membeli. Last-click search dapat mengambil credit; network rules menentukan affiliate credit. Analysis perlu memahami overwrite rules and assisted role.",
["<b>Map tracking flow.</b> Dari click ID/publisher ID menuju redirect, landing, event, validation, and postback.","<b>Define attribution.</b> Tetapkan click/view rules, window, last-click/priority, coupons, and cross-device limitations.","<b>Prevent duplicates.</b> Gunakan order ID/conversion ID, deduplication, and reversal rules.","<b>Reconcile sources.</b> Bandingkan network, marketplace, CRM, and finance records."],
"Buat affiliate attribution flow diagram dan reconciliation workbook: click IDs, sub-IDs, conversion IDs, window, coupon rules, dedupe, cross-device caveats, and sales source.",[["Apa beda attributed sale dan incremental sale?","Attributed sale mendapat credit menurut tracking rule; incremental sale adalah tambahan yang tidak akan terjadi tanpa treatment."],["Apa yang terjadi bila conversion ID tidak unik?","Order dapat tercatat berulang atau gagal dideduplikasi, sehingga conversion, commission, dan payout menjadi tidak akurat."],["Mengapa cookie loss harus dicatat?","Cookie loss dapat menurunkan match dan attribution, sehingga performance partner yang teramati menjadi tidak lengkap."]],[["Click ID","Identifier click untuk menghubungkan traffic ke conversion."],["Attribution window","Attribution window adalah periode ketika conversion dapat dikreditkan ke click atau exposure partner menurut rules program."],["Last click","Aturan memberi credit pada touchpoint click terakhir."],["Cross-device","Cross-device menggambarkan perjalanan pengguna yang berpindah antara beberapa perangkat sebelum menyelesaikan action."]],"DPA-T15-CH06"),
G("Affiliate campaign setup menggabungkan offer, partner groups, commission, creative, feed, landing, tracking, policy, and approval. Campaign structure dapat dipisah menurut SKU/category, geography, partner type, objective, or incentive. Launch checklist harus memastikan product ready, link/UTM/sub-ID valid, discount eligible, commission correct, stock available, and reporting/payout configured.",
"SIMULATED — campaign flash sale mengaktifkan voucher yang tidak berlaku untuk publisher affiliate. Partner mempromosikan harga salah dan order dibatalkan. Offer eligibility and assets must be checked before send.",
["<b>Build campaign brief.</b> Set objectives, products, offer, market, dates, budget/commission, and eligibility.","<b>Prepare partner assets.</b> Provide banners, copy, product feed, links, coupon, disclosure, and restrictions.","<b>Configure tracking/commission.</b> Test publisher IDs, conversion rules, caps, and reversals.","<b>Launch safely.</b> QA stock/price/URL, partner approvals, policy, monitoring, and contact escalation."],
"Buat affiliate launch pack untuk 10 publishers: campaign brief, offer matrix, commission, assets, links, product list, eligibility, disclosure, QA, and launch approval.",
[["Mengapa coupon eligibility harus jelas?","Partner dapat menjanjikan discount yang tidak bisa digunakan sehingga returns/cancellations and trust issues naik."],["Apa yang harus dipantau saat launch?","Click, conversion, AOV, stock, orders, cancellations, invalid orders, link errors, and partner policy compliance."],["Apa pentingnya launch approval?","Memastikan product, legal, pricing, finance, tracking, and partner terms disetujui sebelum campaign aktif."]],[["Offer matrix","Offer matrix mencatat promo, SKU, eligibility, price, commission, stock, dan terms yang berlaku untuk partner."],["Affiliate link","Tracking URL yang mengidentifikasi partner/campaign."],["Campaign cap","Campaign cap membatasi budget, commission, conversion, atau volume sesuai batas yang disetujui advertiser."],["Launch checklist","Quality gate sebelum program berjalan."]],"DPA-T15-CH07"),
G("Creator affiliate/social commerce menggabungkan content, live, short video, product showcase, shopping links, and commission. Creator performance harus dinilai melalui content quality, product demonstration, audience relevance, click/shop conversion, returns, and commission. Platform-native programs memiliki product eligibility, commission rates, content policy, settlement, and attribution rules yang dapat berubah; jangan menjanjikan akses jika seller/creator tidak eligible.",
"SIMULATED — TikTok creator live menghasilkan GMV tinggi tetapi return rate juga tinggi karena product demo misleading. Program perlu quality control, content accuracy, order validation, and commission reversal.",
["<b>Define creator role.</b> Product education, discovery, live demo, review, conversion, or repeat.","<b>Set commission/content rules.</b> Commission, eligible SKU, disclosure, claims, live rules, and content deliverables.","<b>Track performance quality.</b> Views, product clicks, add-to-cart, orders, cancellations, returns, and new-to-brand.","<b>Optimize relationships.</b> Support content, exclusive offers, live schedule, and quality guardrails."],
"Buat social commerce creator program untuk lima SKUs: creator tiers, commission, product feed, live/video brief, claim restrictions, tracking, order quality, returns, and payout conditions.",
[["Mengapa GMV tidak sama dengan net sales/profit?","GMV dapat mencakup cancellations/returns/discounts and does not subtract product, fulfillment, and commission costs."],["Apa risiko creator claims tidak akurat?","Misleading product promises can cause complaints, returns, policy violations, and brand trust harm."],["Mengapa platform program terms harus dicek ulang?","Eligibility, campaign type, commission, attribution, and settlement rules can change by account/category/market."]],[["GMV","Gross Merchandise Value; nilai transaksi sebelum adjustment tertentu."],["Return rate","Return rate mengukur proporsi order atau produk yang dikembalikan dari total basis penjualan yang ditetapkan."],["Social commerce","Social commerce adalah aktivitas discovery, engagement, dan transaksi yang terjadi melalui social content, live, atau in-app shop."],["Creator commission","Komisi atas eligible creator-attributed action/sale."]],"DPA-T15-CH08"),
G("Fraud and traffic quality controls melindungi advertiser dari non-human clicks, cookie stuffing, click injection, fake orders, coupon abuse, incentivized traffic violations, and brand bidding violations. Tidak semua spike adalah fraud; detection harus menggunakan pattern, source, timestamps, device, conversion validation, and partner communication. Contract perlu memberi hak audit, suspend, reversal, and clawback.",
"SIMULATED — publisher menghasilkan click spike dengan zero engagement dan conversion timestamp hampir bersamaan. Ini red flag untuk investigation, bukan langsung bukti final; audit log dan source are needed.",
["<b>Define policy.</b> Daftar prohibited methods, eligible sources, disclosure, brand terms, and data restrictions.","<b>Monitor signals.</b> Periksa click spikes, repeated IP/device, time-to-convert, duplicate orders, coupon leakage, and source mismatch.","<b>Investigate fairly.</b> Collect evidence, contact partner, compare other sources, and classify confidence.","<b>Enforce controls.</b> Hold commissions, reverse invalid conversions, suspend, clawback, or reinstate based on evidence/contract."],
"Buat affiliate fraud playbook: risk taxonomy, monitoring alerts, investigation checklist, evidence log, partner communication, reversal/clawback rules, and escalation.",[["Apakah click spike otomatis fraud?","Tidak; promotions/events can cause spikes. Use multiple signals and investigation before final decision."],["Apa itu cookie stuffing?","Praktik menyisipkan tracking cookie tanpa valid user click/consent untuk mengambil attribution credit."],["Mengapa fraud policy harus tertulis di contract?","Klausul tertulis memberi dasar untuk audit, hold, reversal, suspension, clawback, dan dispute resolution secara konsisten."]],[["Click injection","Click injection adalah praktik fraud yang menyisipkan click palsu agar conversion diklaim oleh partner yang tidak menghasilkan referral sah."],["Cookie stuffing","Memasang tracking identifiers tanpa user action yang sah."],["Invalid conversion","Order/lead yang tidak memenuhi eligibility/quality rules."],["Clawback","Pengambilan kembali commission yang telah dibukukan/dibayar."]],"DPA-T15-CH09"),
G("Commission reconciliation menghitung eligible sales, cancellations, returns, duplicate orders, attribution rules, commission tiers, tax, payout currency, and invoice. Affiliate platform report tidak selalu sama dengan finance/marketplace due to delay or reversal windows. Reconciliation harus memiliki period, order IDs, partner IDs, rate table version, and approval trace.",
"SIMULATED — network melaporkan 1.000 sales, marketplace confirms 920 shipped orders, and finance 870 net paid after return/cancel. Payout should follow contract's eligible basis, not assume network clicks are final sales.",
["<b>Set reporting cut-off.</b> Tentukan order status, return window, currency, tax, and commission period.","<b>Match records.</b> Join order IDs, publisher IDs, SKU, date, status, and commission table.","<b>Calculate payout.</b> Apply reversals, tiers, caps, adjustments, and approved bonuses.","<b>Close disputes.</b> Document evidence, partner queries, credit/debit notes, and payment approvals."],
"Buat monthly commission reconciliation workbook untuk 30 synthetic orders. Hitung eligible, cancelled, returned, duplicate, net commission, tax, payout, variance, and approval.",[["Mengapa network conversions belum final payout?","Conversion masih dapat pending, cancelled, returned, invalid, atau di luar eligibility program sebelum komisi disahkan."],["Apa pentingnya rate table version?","Commission dapat berubah menurut tanggal, partner, atau produk; rate table yang salah menimbulkan kesalahan pembayaran."],["Apa yang harus dilakukan saat partner dispute?","Sediakan order-level evidence, aturan program, source reconciliation, dan resolution timeline yang transparan untuk menyelesaikan dispute."]],[["Commission reconciliation","Commission reconciliation mencocokkan conversion yang eligible dengan rate, approval, reversal, dan payout partner."],["Reversal","Pengurangan commission atas order tidak eligible."],["Payout","Payout adalah pembayaran komisi final kepada partner setelah validasi conversion dan settlement rules."],["Rate table","Daftar commission rates dan effective dates."]],"DPA-T15-CH10"),
G("Affiliate optimization and partner growth meningkatkan quality and contribution, bukan sekadar jumlah publishers. Segment partner by type, quality, value, activity, new-to-brand, category, order value, returns, commission, incrementality, and compliance. Growth levers include exclusive offers, product feed, content support, tiering, creator programs, and improved landing/stock. Partner activation and retention need relationship management and fair terms.",
"SIMULATED — 10% partner menghasilkan 80% net contribution; beberapa coupon partners merebut last-click dari returning customers. Growth plan mengalihkan reward ke niche content partners and creator programs with better acquisition quality.",
["<b>Segment partner performance.</b> Use type, quality, value, activity, new-to-brand, returns, and contribution.","<b>Find growth barriers.</b> Review feed, offer, content, rate, stock, tracking, and support SLA.","<b>Design partner actions.</b> Tier, bonus, exclusive offer, creative kit, content calendar, and retention.","<b>Protect economics.</b> Review incremental profit, commission concentration, risk, and dependency."],
"Buat partner growth scorecard dan 90-day action plan: activation, active rate, net sales, margin, new-to-brand, returns, fraud, commission, and partner tier.",
[["Mengapa jumlah publisher bukan KPI utama?","Program size can rise while active quality, incremental profit, and compliance fall."],["Apa beda active partner rate dan recruited count?","Active rate measures partners generating eligible activity; recruited count only measures enrollment."],["Mengapa concentration risk perlu dipantau?","Revenue/attribution from few partners creates dependency and vulnerability to policy or traffic change."]],[["Active partner rate","Proporsi partner yang menghasilkan eligible activity."],["Partner tiering","Partner tiering mengelompokkan partner berdasarkan quality, value, volume, compliance, atau persyaratan program."],["Contribution profit","Profit after relevant variable costs and commissions."],["Concentration risk","Concentration risk muncul ketika bisnis terlalu bergantung pada sedikit partner, publisher, atau sumber traffic."]],"DPA-T15-CH11"),
G("Affiliate Capstone menyatukan commercial model, recruitment, platform/feed, tracking, campaign, quality control, reconciliation, and partner growth. Pekerjaan harus memperlihatkan unit economics dan payout rules, bukan hanya link creation. Data synthetic harus diberi label dan platform access/terms diverifikasi per account. Portfolio perlu menunjukkan bagaimana program menjaga advertiser margin dan fair partner measurement.",
"SIMULATED — retailer ingin meningkatkan sales kategori dengan affiliate network, creator live, and content publishers. Capstone menetapkan commission tiers, product feed, tracking, fraud controls, returns reconciliation, and 90-day partner growth plan.",
["<b>Frame the program.</b> Set objective, product economics, eligible conversion, partner mix, and market.","<b>Build partner engine.</b> Discovery, onboarding, terms, assets, feed, links, and activation.","<b>Control measurement/finance.</b> Validate tracking, fraud, conversion status, commission, and payout.","<b>Grow responsibly.</b> Optimize partner portfolio by incremental contribution and trust."],
"Bangun affiliate capstone pack: program brief, ecosystem map, partner shortlist, commission model, feed/link QA, campaign plan, fraud playbook, reconciliation workbook, partner dashboard, and executive recommendation.",
[["Apa bukti program affiliate siap diluncurkan?","Clear economics, conversion rules, contract, feed, tracking QA, partner policy, fraud control, and finance reconciliation."],["Bagaimana membuktikan affiliate menguntungkan?","Gunakan incremental contribution after discount, fees, returns, and commission; do not rely on gross sales/attributed ROAS only."],["Apa yang perlu dicantumkan dalam portfolio?","Artifacts, formulas, sources, assumptions, simulated labels, risk controls, and learning—not invented sales results."]],
[["Affiliate operating model","Struktur partner, commission, tracking, governance, and finance."],["Net contribution","Contribution after discounts, returns, fees, and commission."],["Partner portfolio","Komposisi partner menurut type, quality, and value."],["Affiliate capstone","Kasus end-to-end program performance partnership."]],"DPA-T15-CH12")
],
community:[
G("Community strategy menetapkan mengapa komunitas perlu ada, siapa yang dilayani, nilai yang diberikan, rules, participation model, and expected business/customer impact. Komunitas dapat brand-owned, platform-based, customer-led, professional, or interest-based. Tujuan bukan hanya menambah anggota; community health mencakup trust, participation, safety, retention, and mutual value. Tidak semua brand membutuhkan komunitas milik sendiri.",
"SIMULATED — brand memiliki 100 ribu followers tetapi percakapan dan repeat contributors sangat sedikit. Strategi perlu menentukan purpose: support, peer learning, product feedback, advocacy, or shared interest, bukan membuat grup baru hanya demi angka anggota.",
["<b>Define purpose.</b> Tulis value untuk anggota dan brand; jangan mulai dari pilihan platform.","<b>Choose community model.</b> Tentukan owned/platform/customer-led, open/closed, and participation level.","<b>Set success framework.</b> Definisikan activation, participation quality, retention, safety, and customer outcomes.","<b>Govern it.</b> Tetapkan owner, moderation policy, resources, privacy, and escalation."],
"Buat community charter: purpose, member promise, target segments, platform rationale, entry rules, participation principles, governance, and measurable success criteria.",
[["Apa beda audience dan community?","Audience menerima konten; community memiliki interaksi, norma, hubungan antar anggota, dan partisipasi berkelanjutan."],["Kapan brand tidak perlu membuat community sendiri?","Saat audience sudah terlayani di ruang lain, value proposition komunitas tidak jelas, atau resource moderation tidak tersedia."],["Mengapa member count bukan ukuran health?","Anggota bisa pasif, tidak relevan, atau tidak aman; participation, trust, retention, and value lebih penting."]],
[["Community purpose","Alasan/nilai komunitas ada bagi anggota dan brand."],["Community health","Kualitas participation, trust, safety, and retention."],["Owned community","Ruang komunitas yang dikelola/dimiliki brand."],["Community charter","Dokumen purpose, rules, roles, and governance."]],"DPA-T16-CH01"),
G("Community mapping mengidentifikasi ruang audience berkumpul, norms, influential members, moderators, critics, advocates, and unmet needs. Mapping perlu membedakan platform audience dari community participants dan memperhatikan public/private spaces. Listening harus menghormati privacy, context, and platform terms; jangan mengumpulkan data pribadi tanpa kebutuhan/izin.",
"SIMULATED — skincare audience berdiskusi di forum, comments, groups, and review pages. Setiap ruang memiliki tone/rules berbeda; brand perlu memahami norma sebelum masuk dengan promosi.",
["<b>Map spaces.</b> Catat platform, group/forum, topic, access, size indicators, and rules.","<b>Identify roles.</b> Bedakan lurkers, contributors, moderators, experts, advocates, critics, and brand accounts.","<b>Read norms.</b> Pelajari language, trust, promotion tolerance, conflict, and participation rituals.","<b>Document risk/value.</b> Catat privacy, safety, relevance, and community expectations."],
"Buat audience community map untuk satu kategori dengan 10 public spaces/accounts, member roles, norms, high-value conversations, risk, and ethical engagement approach.",[["Mengapa brand tidak boleh langsung masuk dengan promosi?","Community memiliki norma dan trust sendiri; promosi tanpa permission atau value dapat dianggap spam dan merusak hubungan."],["Apa beda lurker dan contributor?","Lurker mengamati tanpa aktif posting; contributor memberi pertanyaan, jawaban, content, or participation."],["Apa etika social listening?","Ikuti platform rules, minimize personal data, respect private spaces, and report aggregate/context rather than exposing individuals."]],
[["Lurker","Anggota yang mengamati tetapi jarang berkontribusi."],["Contributor","Anggota yang aktif memberi konten/komentar/pertanyaan."],["Community norms","Aturan formal/informal dalam ruang komunitas."],["Social listening","Pemantauan percakapan publik untuk memahami topic/sentiment/context."]],"DPA-T16-CH02"),
G("Community platform selection mempertimbangkan audience presence, conversation type, moderation capability, privacy, discoverability, searchability, features, member expectations, and operational burden. Segmentasi member dapat berdasarkan stage, expertise, interest, contribution, and support needs. Jangan memilih WhatsApp/Discord/Telegram hanya karena populer; platform harus sesuai purpose and safety requirements.",
"SIMULATED — community untuk customer support memerlukan searchable knowledge and ticket handoff; grup chat dengan volume tinggi sulit dicari dan dimoderasi. Forum/help center mungkin lebih tepat.",
["<b>Define use case.</b> Support, education, peer advice, advocacy, co-creation, or events.","<b>Compare platforms.</b> Nilai access, discovery, moderation tools, analytics, privacy, search, roles, and integration.","<b>Design segments/roles.</b> New members, experts, advocates, moderators, and customers at risk.","<b>Set onboarding.</b> Welcome, rules, profile/data minimization, prompts, and escalation path."],
"Buat platform decision matrix untuk tiga opsi komunitas: objective, user behavior, moderation tools, privacy, analytics, integrations, cost, and risk. Sertakan member segmentation.",[["Mengapa platform harus mengikuti use case?","Setiap platform memiliki conversation format, search, roles, privacy, and moderation constraints berbeda."],["Apa risiko community group tanpa moderation capacity?","Spam, misinformation, harassment, privacy issues, and customer harm can grow faster than support resources."],["Apa yang perlu dikumpulkan saat onboarding?","Kumpulkan profile dan preference minimum yang diperlukan untuk tujuan jelas; hindari data pribadi yang tidak relevan."]],[["Community platform","Ruang digital untuk interaksi komunitas."],["Onboarding","Proses menyambut dan membantu anggota memahami rules/value."],["Member segment","Member segment mengelompokkan anggota berdasarkan kebutuhan, lifecycle stage, behaviour, atau kontribusi komunitas."],["Moderation capacity","Resource/tool/time untuk menjaga safety and quality."]],"DPA-T16-CH03"),
G("Social listening and conversation intelligence mengubah percakapan menjadi insight melalui query design, source coverage, Boolean logic, taxonomy, sentiment/context coding, topic clustering, trend detection, and reporting. Sentiment automation tidak memahami seluruh ironi/slang/bahasa campuran; analyst harus melakukan manual validation. Volume mention bukan otomatis market opinion atau representative survey.",
"SIMULATED — tool mengklasifikasikan 'parah bagus' sebagai negative, padahal slang berarti positif. Bahasa Indonesia, code-switch, sarcasm, and context memerlukan sampling manual dan codebook.",
["<b>Design queries.</b> Buat brand/product/category/competitor terms, synonyms, exclusions, and language variants.","<b>Validate coverage.</b> Uji recall/precision sample, platform coverage, private-space limits, and query noise.","<b>Code conversations.</b> Klasifikasikan topic, sentiment/context, need, question, issue, and influence.","<b>Translate to action.</b> Susun insight, confidence, escalation, content, product, and service implications."],
"Buat listening query set dan coding book untuk brand/kategori. Analisis 100 synthetic/public-safe mentions: topic, sentiment, intent, audience tension, false positives, and recommended actions.",[["Mengapa automated sentiment perlu human QA?","Slang, sarcasm, context, dan mixed language dapat salah diklasifikasikan oleh model, sehingga human review tetap diperlukan."],["Apa beda mention volume dan sentiment?","Mention volume menghitung percakapan; sentiment menafsirkan tone dan context, sehingga memerlukan validasi serta sampling."],["Mengapa query exclusions penting?","Exclusions mengurangi irrelevant mentions, homonyms, spam, dan false positives agar social listening tidak menghasilkan insight keliru."]],[["Boolean query","Kombinasi operator untuk menyaring mention."],["Sentiment coding","Sentiment coding mengklasifikasikan tone atau attitude percakapan dengan mempertimbangkan konteks, bahasa, dan tujuan analisis."],["Recall","Proporsi relevant mentions yang berhasil ditemukan."],["Precision","Proporsi found mentions yang benar-benar relevant."]],"DPA-T16-CH04"),
G("Community management menjalankan interaksi harian dan membangun participation. Community manager menjawab pertanyaan, memfasilitasi peer support, welcome newcomers, maintain tone, detect friction, and protect trust. Response quality harus akurat, human, timely, and consistent; jangan menjanjikan hal yang tidak dapat dipenuhi. SLA dibedakan berdasarkan question, complaint, safety, and crisis severity.",
"SIMULATED — pengguna bertanya tentang product allergy. Community manager tidak boleh memberi diagnosis medis; ia merespons secara empatik, merujuk label/support team, and escalates potential safety issue.",
["<b>Set response principles.</b> Tone, accuracy, empathy, boundaries, and source-of-truth.","<b>Design engagement routines.</b> Welcome, conversation prompts, peer connections, event, and follow-up.","<b>Set SLA and routing.</b> Categorize question/complaint/safety/legal with owner and due time.","<b>Record outcomes.</b> Track resolution, repeat issues, member feedback, and escalation."],
"Buat response playbook 20 cases: question, praise, complaint, misinformation, product issue, crisis signal, safety concern, and spam. Include response, owner, SLA, and escalation.",
[["Apa beda community management dan customer care?","Community management mengelola relationship/participation; customer care menyelesaikan service cases dengan systems/SLA—keduanya perlu handoff."],["Mengapa response template tidak boleh kaku?","Context, emotion, and issue severity require human adaptation; template supports consistency, not robotic replies."],["Kapan harus escalate product safety?","Saat ada injury, adverse reaction, contamination, or serious risk; follow approved safety/legal protocol immediately."]],
[["Community engagement","Interaksi untuk participation and relationship."],["Response SLA","Target waktu respon menurut severity."],["Escalation","Pengalihan issue ke owner/authority yang tepat."],["Community care","Service/support yang diberikan melalui community/social channels."]],"DPA-T16-CH05"),
G("Content programming membuat komunitas memiliki alasan untuk kembali dan berkontribusi. Program dapat berupa AMA, challenge, peer learning, feedback sessions, events, member stories, product clinics, and co-creation. Editorial plan harus mengikuti community questions and rhythms, bukan hanya brand broadcast. UGC membutuhkan permission, context, credit, rights, moderation, and safety review.",
"SIMULATED — brand membuat weekly challenge tetapi hadiah hanya mendorong low-quality spam. Program yang lebih baik memberi shared value: peer tips, expert feedback, recognition, or meaningful access.",
["<b>Start from member needs.</b> Pilih theme/format dari listening and recurring questions.","<b>Design participation.</b> Tetapkan prompt, entry mechanics, reward/value, moderation, and inclusion.","<b>Plan content rhythm.</b> Susun recurring programs, community milestones, and event calendar.","<b>Manage UGC rights.</b> Obtain permission, source/credit, platform usage, edit approval, and retention."],
"Buat 4-week community program calendar dengan 2 recurring formats, one event/AMA, UGC process, moderation roles, participation metric, and safety plan.",[["Mengapa challenge dengan hadiah saja dapat gagal?","It can attract incentive-only behavior without meaningful member value or durable participation."],["Apa yang perlu sebelum repost UGC?","Pastikan permission, attribution atau credit, usage scope, editing consent, dan compliance review sebelum UGC dipublikasikan ulang."],["Bagaimana mengukur programming quality?","Repeat contributors, meaningful replies, completion, member value, retention, and issue reduction—not raw posts alone."]],[["Community programming","Rangkaian aktivitas/konten untuk memfasilitasi participation."],["AMA","Ask Me Anything; format tanya jawab."],["UGC","User-generated content adalah materi yang dibuat pengguna atau anggota komunitas, bukan diproduksi langsung oleh brand."],["Participation loop","Pola prompt-contribution-response-recognition yang mendorong partisipasi ulang."]],"DPA-T16-CH06"),
G("Moderation dan guidelines menjaga keamanan, trust, and brand suitability. Policy perlu mendefinisikan spam, harassment, hate, misinformation, personal data, threats, illegal activity, and product claims. Moderation ladder menentukan hide, remove, warn, mute, ban, or escalation; keputusan harus konsisten, documented, and appealable bila sesuai. Brand safety bukan berarti menghapus kritik yang sah.",
"SIMULATED — pelanggan menulis kritik produk bercampur bahasa kasar tetapi tidak abusive. Moderator perlu membedakan complaint legitimate dari harassment; menghapus semua kritik akan merusak trust.",
["<b>Write guidelines.</b> Definisikan accepted behavior, prohibited content, consequences, privacy, and appeals.","<b>Build moderation matrix.</b> Tentukan severity, response, evidence, owner, and escalation.","<b>Train moderators.</b> Gunakan scenarios, consistency calibration, and sensitive-case protocols.","<b>Audit decisions.</b> Review false positives/negatives, appeal, fairness, and member safety."],
"Buat community rules dan moderation matrix dengan 10 scenarios, severity, action, response template, evidence retention, appeal, and escalation owner.",[["Mengapa kritik sah tidak boleh dihapus otomatis?","Feedback yang sah memberi evidence dan trust; moderation harus menargetkan harmful behavior, bukan negative sentiment."],["Apa yang dilakukan pada doxxing/personal data exposure?","Hide atau remove segera, simpan evidence minimum, eskalasi ke security/legal, dan lindungi anggota yang terdampak."],["Mengapa moderation harus memiliki appeal/escalation path?","Appeal path meningkatkan konsistensi dan fairness serta memungkinkan review atas keputusan moderation yang berdampak pada anggota."]],
[["Moderation","Pengelolaan konten/perilaku sesuai community rules."],["Doxxing","Publikasi data pribadi untuk menyerang/mengancam."],["Severity matrix","Klasifikasi tingkat issue dan action."],["Appeal","Permintaan review atas moderation decision."]],"DPA-T16-CH07"),
G("Customer care via community/social harus menghubungkan public response dengan private case handling. Community manager perlu memahami privacy, verification, ticketing, SLA, escalation, and crisis boundaries. Jangan meminta nomor order/PII di public comments; arahkan ke secure channel. Public response tetap perlu menunjukkan ownership tanpa membocorkan data customer.",
"SIMULATED — pelanggan mengunggah nomor telepon dan order ID di komentar. Community manager meminta penghapusan/menyembunyikan data, memindahkan percakapan ke secure ticket, and memastikan public follow-up setelah resolution.",
["<b>Classify case.</b> Pisahkan inquiry, complaint, transaction, safety, privacy, and legal issue.","<b>Protect data.</b> Jangan meminta/mengulang PII di publik; gunakan verified private channel.","<b>Route and track.</b> Buat ticket, assign owner, SLA, case status, and update cadence.","<b>Close the loop.</b> Pastikan resolution, public acknowledgement where appropriate, and root-cause feedback."],
"Buat customer care handoff flow dan response templates untuk order issue, refund, product defect, privacy complaint, and safety incident. Sertakan PII rules and SLA.",[["Mengapa case perlu dipindah ke secure channel?","Secure channel melindungi PII dan order details, serta menjaga verification dan records sesuai service process."],["Apa bedanya acknowledge dengan resolve?","Acknowledge berarti mengakui issue telah diterima; resolve berarti masalah ditangani dan outcome dikonfirmasi kepada pihak terkait."],["Apa yang harus dicatat di ticket?","Case ID, category, owner, SLA, status, evidence, action, and closure—minimum necessary personal data."]],[["Customer care","Service support untuk menyelesaikan customer issue."],["PII","Personally Identifiable Information adalah informasi yang dapat mengidentifikasi seseorang secara langsung atau melalui kombinasi data."],["Ticket","Record terstruktur untuk case/issue handling."],["Closure","Konfirmasi penyelesaian dan status akhir case."]],"DPA-T16-CH08"),
G("Advocacy dan UGC membangun hubungan sehingga member secara sukarela membantu brand melalui recommendation, review, referrals, content, feedback, and peer support. Advocacy program harus memberi recognition/value tanpa membeli opini atau memaksa positive reviews. Permission, disclosure, incentives, content rights, and authenticity perlu diatur. Advocate bukan sekadar member dengan follower tinggi; trust dan helpful contribution lebih penting.",
"SIMULATED — brand memberi reward hanya untuk review bintang lima. Itu mendorong bias dan berisiko melanggar platform policies. Program yang sehat memberi reward atas partisipasi/feedback tanpa mengontrol sentiment.",
["<b>Define advocacy behaviors.</b> Referral, helpful answers, UGC, reviews, beta feedback, or event participation.","<b>Design recognition.</b> Rewards, access, education, status, or community value without buying positive sentiment.","<b>Secure consent/rights.</b> Obtain content permissions and disclosure for incentivized activity.","<b>Measure trust.</b> Track repeat advocacy, contribution quality, referrals, sentiment context, and member retention."],
"Buat advocacy program blueprint: member tiers/behaviors, recognition system, UGC permission, referral flow, review policy, disclosure, and health metrics.",[["Mengapa reward untuk positive review berisiko?","Mengontrol sentiment dan dapat melanggar review/platform policies; reward should not require positive rating."],["Apa beda advocate dan influencer?","Advocate punya relationship/peer trust through genuine participation; influencer is selected for audience/content reach, though overlap exists."],["Apa yang perlu sebelum memakai UGC brand-wide?","Konfirmasi permission, credit, channel, period, editing rules, disclosure, dan rights untuk setiap penggunaan yang direncanakan."]],[["Advocacy","Perilaku mendukung/merekomendasikan brand secara sukarela."],["UGC rights","Izin menggunakan content yang dibuat user."],["Peer recommendation","Peer recommendation adalah rekomendasi dari pengguna atau anggota lain yang berbagi pengalaman atau pengetahuan."],["Recognition","Recognition adalah bentuk pengakuan atas kontribusi anggota melalui apresiasi, status, atau reward yang sesuai."]],"DPA-T16-CH09"),
G("Crisis monitoring mengamati early signals, complaint velocity, sentiment/context, safety reports, influential actors, and potential escalation. Crisis playbook harus mendefinisikan trigger, severity, spokesperson, legal/PR/customer care owners, holding statement, approval, evidence preservation, and updates. Community manager tidak boleh berspekulasi atau menghapus kritik substansial; ia harus menjaga factuality, empathy, and escalation.",
"SIMULATED — rumor kualitas produk menyebar dan ada satu report adverse effect. Tim perlu membedakan rumor, verified safety incident, and misinformation; issue harus di-escalate ke product safety/legal sebelum brand membuat statement.",
["<b>Set early-warning rules.</b> Monitor volume spikes, risk keywords, safety terms, influential posts, and cross-platform spread.","<b>Classify severity.</b> Tentukan service, reputation, safety, legal, or security issue.","<b>Activate playbook.</b> Assign incident lead, verify facts, approve statement, route cases, and time updates.","<b>Review after crisis.</b> Document timeline, root causes, response effectiveness, member impact, and prevention."],
"Buat crisis playbook dengan 5 scenarios, severity triggers, RACI, holding statement, approval chain, response SLA, evidence log, and after-action review.",
[["Mengapa holding statement harus hati-hati?","Fakta belum lengkap; statement harus acknowledge, explain next step, and avoid unsupported claims or blame."],["Kapan issue berubah menjadi crisis?","Saat scope, safety/legal risk, rapid spread, business impact, or stakeholder attention melewati escalation threshold."],["Apa yang perlu dilakukan setelah crisis?","Audit timeline, decisions, response, harm, root cause, and prevention; do not simply delete posts."]],[["Early warning signal","Early warning signal adalah indikator awal yang dapat menandakan peningkatan risiko, keluhan, atau potensi crisis."],["Holding statement","Pernyataan awal saat investigasi masih berjalan."],["Incident lead","Incident lead adalah pihak yang mengoordinasikan respons, keputusan, komunikasi, dan eskalasi selama penanganan incident."],["After-action review","Evaluasi response dan prevention setelah incident."]],"DPA-T16-CH10"),
G("Community measurement mengukur health dan value: active members, repeat contributors, meaningful conversation, response SLA, resolution, sentiment/context, retention, safety incidents, UGC quality, referral, and customer outcomes. Metrics perlu denominator, period, segment, and sampling method. Follower/member count tidak menunjukkan value tanpa participation. Report harus memadukan quantitative trend dan qualitative examples.",
"SIMULATED — community growth naik 40% setelah giveaway, tetapi repeat contributors turun dan spam meningkat. Member count meningkat tanpa health; segmentation and behavior metrics menunjukkan quality decline.",
["<b>Define health dimensions.</b> Acquisition, activation, contribution, connection, retention, safety, and value.","<b>Build metrics.</b> Active member rate, repeat contributor, response/resolution, moderation, and meaningful actions.","<b>Combine quant and qual.</b> Trend data dengan conversation examples and member feedback.","<b>Recommend action.</b> Hubungkan findings ke programming, moderation, service, and product changes."],
"Buat community health dashboard dan monthly report: active members, contributor rate, repeat, SLA, resolution, moderation, sentiment themes, UGC permissions, and next actions.",[["Mengapa member count tidak cukup?","Member growth dapat berasal dari campaign atau giveaway; ukur active, retained, helpful, dan recurring participation untuk menilai kualitas."],["Apa definisi meaningful contribution?","Action yang memberi value pada komunitas seperti jawaban, feedback, support, content, or constructive discussion."],["Mengapa sentiment score harus divalidasi?","Language, sarcasm, sample bias, dan platform coverage dapat menyebabkan misclassification; audit sample secara manual sebelum mengambil keputusan."]],
[["Active member rate","Proporsi anggota yang melakukan activity terdefinisi."],["Contributor rate","Proporsi anggota yang memberi kontribusi."],["Response SLA","Target waktu respons untuk komentar/case."],["Community retention","Anggota yang kembali aktif dalam window berikutnya."]],"DPA-T16-CH11"),
G("Community Capstone menyatukan purpose, audience mapping, platform selection, listening, engagement, programming, moderation, customer care, advocacy, crisis, and measurement. Deliverable harus operasional: charter, governance, calendar, response bank, escalation, and dashboard. Community bukan sekadar group chat; keberhasilannya diukur dari value dan safety bagi anggota serta dampaknya pada relationship/customer experience.",
"SIMULATED — brand membuat community 90 hari untuk pelanggan baru dan power users. Capstone merancang onboarding, peer learning, product feedback, moderation, support escalation, UGC permission, and advocate recognition.",
["<b>Frame community value.</b> Tetapkan member promise, role, audience, and purpose.","<b>Design operations.</b> Pilih platform, segments, programming, moderation, customer care, and governance.","<b>Activate relationships.</b> Onboard members, encourage participation, support advocates, and manage risk.","<b>Measure health.</b> Track retention, participation, safety, resolution, and business/customer value."],
"Bangun community operating pack: charter, audience map, platform decision, onboarding, 4-week calendar, moderation matrix, care handoff, advocacy program, crisis playbook, dashboard, and after-action plan.",
[["Apa yang membedakan community plan dari social content calendar?","Community plan mengatur member relationships, participation, norms, service, safety, and governance—not only publishing."],["Bagaimana membuktikan community value?","Show member outcomes, repeat participation, resolution, feedback, advocacy, retention, and measured business/service effects."],["Apa yang harus dihindari dalam capstone?","Fake member counts, fabricated sentiment, forced testimonials, unsafe data collection, and unapproved UGC use."]],[["Community operating model","Model operasi untuk purpose, members, content, moderation, service, and measurement."],["Participation","Participation mengukur keterlibatan anggota melalui aktivitas, kontribusi, atau interaksi bermakna di komunitas."],["Advocacy loop","Mekanisme value dan recognition yang mendorong genuine recommendation."],["Community capstone","Paket implementasi dan governance komunitas end-to-end."]],"DPA-T16-CH12")
]
};
Object.assign(ROLE_STUDY_GUIDES, ROLE_STUDY_GUIDES_PART3);
